use vstd::prelude::*;

verus! {
    // Specification: the minimal number of operations to make a,b,c equal
    // when you may either add 2 to a single element, or add 1 to two distinct elements.
    spec fn needed_ops(a: nat, b: nat, c: nat) -> nat {
        // sort into x ≤ y ≤ z
        let x = nat::min(a, nat::min(b, c));
        let z = nat::max(a, nat::max(b, c));
        let y = a + b + c - x - z;
        // total deficit w.r.t. target = z
        let S = 2*z - x - y;
        if S % 2 == 0 {
            S / 2
        } else {
            // if S is odd, we must raise the target by 1
            // which increases the sum of deficits by 3, and  (S+3)/2 ops
            (S + 3) / 2
        }
    }

    fn solve(a: i8, b: i8, c: i8) -> (result: i8)
        requires
            0 <= a && a <= 50,
            0 <= b && b <= 50,
            0 <= c && c <= 50,
        ensures
            // result is non‐negative
            0 <= result,
        ensures
            // and agrees with our spec
            result as nat == needed_ops(a as nat, b as nat, c as nat),
    {
        // lift to wider type to avoid overflow when computing S
        let mut x: i16 = a as i16;
        let mut y: i16 = b as i16;
        let mut z: i16 = c as i16;

        // 3‐way sort: afterwards x ≤ y ≤ z
        if x > y { let t = x; x = y; y = t; }
        if y > z { let t = y; y = z; z = t; }
        if x > y { let t = x; x = y; y = t; }

        // S = 2*z - x - y; must be ≥ 0
        let S: i16 = 2*z - x - y;
        assert(S >= 0); // since z ≥ x,y

        // now match the same formula as in needed_ops
        if S % 2 == 0 {
            // even case
            let r_i16 = S / 2;
            assert(0 <= r_i16); // S>=0
            let r = r_i16 as i8;
            // prove r matches the spec
            proof {
                // compute the same S in nat
                let x_nat = x as nat;
                let y_nat = y as nat;
                let z_nat = z as nat;
                let S_nat = 2*z_nat - x_nat - y_nat;
                assert(S_nat == S as nat);
                assert(S_nat % 2 == 0);
                assert(r as nat == S_nat / 2);
            }
            result = r;
        } else {
            // odd case
            let r_i16 = (S + 3) / 2;
            assert(0 <= r_i16); 
            let r = r_i16 as i8;
            // prove r matches the spec
            proof {
                let x_nat = x as nat;
                let y_nat = y as nat;
                let z_nat = z as nat;
                let S_nat = 2*z_nat - x_nat - y_nat;
                assert(S_nat == S as nat);
                assert(S_nat % 2 == 1);
                // in spec: (S_nat + 3)/2
                assert(r as nat == (S_nat + 3) / 2);
            }
            result = r;
        }
    }
}

